function FriendMain:Awake()
    self.maxFriendNum = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting11, "FriendArgVo", 1).num)--好友参数表中的好友数量上限
    self.maxDrawFriendGift = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting11, "FriendArgVo", 2).num)--好友收取体力次数上限
    self.maxGiveFriendGift = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting11, "FriendArgVo", 7).num)--好友赠送体力次数上限
    self.pvpWaitTime = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting11, "FriendArgVo", 6).num)--好友参数表中的好友切磋邀请待处理时间（秒）
    
    KTool.SetActive(self.BtnReset, false)
    SetButtonAction(self.BtnReset, function ()
        self.InputField.text = ""
        KTool.SetActive(self.BtnReset, false)
        self:FreshAddFriendPanel(self.recommendFriendList)
    end)

    self.InputField.onEndEdit:AddListener(function()
        if string.len(self.InputField.text) > 0 then
            KTool.SetActive(self.BtnReset, true)
        elseif string.len(self.InputField.text) == 0 then
            KTool.SetActive(self.BtnReset, false)
        end
    end)

    SetButtonAction(self.BtnSetting, function ()
        KCookie.Set("SettingOpenType", 4)
        UIModule.OpenDialog({id = Constants.UITypeIds.UISettingDialog}, { { id = Constants.UITypeIds.FriendMain } })
    end)

    SetButtonAction(self.BtnAgreeAll, function()
        GameUtils.Request(Interfaces.FriendHandleDelFriends, {}, function(request, response)
            if checkInt(response.errCode) == 0 then
                self.friendRequest = {}
                self:OnClickTabToggleAction(OpenType.AddFriend)
                GameUtils.SetRedPointNum(Constants.RedPointConst.FriendRequest, 0)
            end
        end)
    end)
    
    SetButtonAction(self.FontStyleButton, Bind(self, self.OneClickBtnHandler))
    GameUtils.BindRedPoint(Constants.RedPointConst.FriendGiftOneClick, self.FontStyleButton.gameObject, true)

    local env = CfUtils.GetLuaScr(self.BtnRefresh, "Game.Behaviours.CommonCDBtn")
    if env then
        env:SetCallBack(function ()
            self:OnClickRefreshBtn()
        end, 5, nil, nil, localize("请稍后尝试"))
    end

    GameUtils.SetCommunityClick(self.BtnCommunity.gameObject, 3)

    SetButtonAction(self.BtnTeam, function()
        UIModule.OpenDialog({ id = Constants.UITypeIds.UIFightTeamChoose, parameters = { levelId = Constants.SpecialQuestId.FriendPVPId, teamIndex = 1 } })
    end)
end

function FriendMain:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self:AddListener()
    end))
    return coWait
end

function FriendMain:OnShow()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            GameUtils.Request(Interfaces.FriendHome, {}, function(request, response)
                if checkInt(response.errCode) == 0 then
                    self:InitData(response.data)
                    self:FreshLeftUI()--刷新左侧UI
                end
            end)
        end)
    end))
    return coWait
end

function FriendMain:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self:RemoveListener()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

---浅拷贝friendComponent的数据，维护的时候统一维护
function FriendMain:InitData(serverData)
    friendComponent:InitialDojo(serverData)--这边初始的数据供其他子节点使用

    self.friendList = friendComponent.friendList
    self.friendRequest = friendComponent.friendRequest
    self.recommendFriendList = friendComponent.recommendFriendList
    self.drawFriendIds = friendComponent.drawFriendIds
    self.giveFriendIds = friendComponent.giveFriendIds
    self.giftList = friendComponent.giftList
    self.requestFriendIds = friendComponent.requestFriendIds
end

function FriendMain:ResetAnimData()
    for i = 1, LoopViewMaxCellCount do
        self["isAnimated"..i] = false
    end
end

function FriendMain:AddListener()
    self:RemoveListener()
    self.EventDelFriend = Events.AddListener("CommonPlayerHead_DelFriend", Bind(self, self.OnDelFriend))
    self.EventFriendInfoChange = Events.AddListener(Constants.EventNames.FriendInfoChange, Bind(self, self.FriendInfoChange))
end

function FriendMain:RemoveListener()
    Events.RemoveListener(Constants.EventNames.FriendInfoChange, self.EventFriendInfoChange)
    Events.RemoveListener("CommonPlayerHead_DelFriend",self.EventDelFriend)
    self.EventDelFriend = nil
end

---刷新左侧面板
function FriendMain:FreshLeftUI()
    local togglesData = {
        [1] = {
            text = localize("好友列表"),
            textColor = {
                default = "#A8A8A8",
                selected = "#FFFFFF"
            },
            selectImgPath = "Arts/Icons/HomeLabel/tab_ico_list.png",
            redPointStrNode = Constants.RedPointConst.FriendGift,
            func = function()
                self:OnClickTabToggleAction(OpenType.FriendList)
                KCookie.Set(NAME, OpenType.FriendList)

            end
        },
        [2] = {
            text = localize("添加好友"),
            textColor = {
                default = "#A8A8A8",
                selected = "#FFFFFF"
            },
            selectImgPath = "Arts/Icons/HomeLabel/tab_ico_Add.png",
            redPointStrNode = Constants.RedPointConst.FriendRequest,
            func = function()
                self:OnClickTabToggleAction(OpenType.AddFriend)
                KCookie.Set(NAME, OpenType.AddFriend)
            end
        }
    }
    local openType = KCookie.Get(NAME)
    if isNull(openType) then
        openType = OpenType.FriendList
    end

    if isNull(self.CommonTabToggleLeft.Env) then
        self.CommonTabToggleLeft:Init()
    end
    self.CommonTabToggleLeft.Env:FillToggles(togglesData, openType)
    togglesData[openType].func()
    
    self:FreshFriendCount()
    self:FreshLeftReceiveTime(friendComponent:GetDrawFriendGiftNum())
end

function FriendMain:OnDelFriend()
    if isNull(self.friendList) then
        self.friendList = {}
    end

    -- 记录现在的列表位置
    local listContent = self.LoopListFriend.transform:Find("Viewport/Content")
    local oldPosition = listContent.localPosition

    self:OnClickTabToggleAction(OpenType.FriendList, true)
    KCookie.Set(NAME, OpenType.FriendList)

    -- 还原列表位置
    listContent.localPosition = oldPosition
end

---接收到红点的点亮，刷新信息
---@param type number OpenType
function FriendMain:FriendInfoChange(type)
    if isNull(type) then
        return
    end
    GameUtils.Request(Interfaces.FriendHome, {}, function(request, response)
        if checkInt(response.errCode) == 0 then
            self:InitData(response.data)
            if (type == OpenType.FriendList and self.isFriendList) or (type == OpenType.AddFriend and (not self.isFriendList)) then--红点为当前界面时刷新当前界面
                self:OnClickTabToggleAction(type)
            end
        end
    end)
end

function FriendMain:OnClickTabToggleAction(type, skipResetAnimData)
    self.isFriendList = type == OpenType.FriendList
    --排序规则：在线状态好友根据角色等级从上至下排序，离线状态好友根据离线时长（由短至长）进行从上至下排序
    table.sort(self.friendList, function (a,b)
        if a.isOnline ~= b.isOnline then
            return a.isOnline > b.isOnline
        elseif a.lastExitTime ~= b.lastExitTime then
            return a.lastExitTime < b.lastExitTime
        elseif a.level ~= b.level then
            return a.level > b.level
        end
    end)
    local isHaveFriendRequest = #self.friendRequest > 0 --有好友申请
    KTool.SetActive(self.InputField, (not self.isFriendList) and (not isHaveFriendRequest))--选择了添加好友界面且没有好友申请
    KTool.SetActive(self.LoopListFriend, self.isFriendList or isHaveFriendRequest)
    KTool.SetActive(self.Layout, (not self.isFriendList) and (not isHaveFriendRequest))--选择了添加好友界面且没有好友申请
    KTool.SetActive(self.ItemEmptyPanel, self.isFriendList and #self.friendList == 0)--选择了好友列表界面且没有好友
    KTool.SetActive(self.BtnAgreeAll, not self.isFriendList and isHaveFriendRequest)
    KTool.SetActive(self.BtnRefresh, not self.isFriendList and not isHaveFriendRequest)
    KTool.SetActive(self.TxtTime, self.isFriendList)
    ---@region重置动画并将起始位置重置
    if not skipResetAnimData then
        self:ResetAnimData()
    end
    local rectView = self.LoopListFriend.gameObject:GetComponent(typeof(ScrollRect))
    rectView.content.localPosition = Vector2.zero
    ---@endregion
    if self.isFriendList then--循环列表
        KTool.SetActive(self.FontStyleButton, true)
        self.FontStyleButton:GetComponent("FontStyleButton"):ResetFontStyle("B6", localize("一键处理"))
        self.cellType = Constants.FriendCellType.FriendList
        if not self.LoopListFriend.IsListViewInit then
            self.LoopListFriend:InitListView(#self.friendList, Bind(self, self.OnGetItemByIndex))
        else
            GameUtils.ReloadData(self.LoopListFriend, #self.friendList)
        end
        -- 在好友列表页签里面要显示红点
        ---@type RedPointMgrComponent
        local redPointCom = GameUtils.GetEntityCompByType(ECSComponentType.Constants.RedPointMgrComponent)
        redPointCom:InvokeCallBack(Constants.RedPointConst.FriendGiftOneClick)
    else
        KTool.SetActive(self.FontStyleButton, true)
        if isHaveFriendRequest then--循环列表
            self.FontStyleButton:GetComponent("FontStyleButton"):ResetFontStyle("B6", localize("一键同意"))
            self.cellType = Constants.FriendCellType.RequestList
            if not self.LoopListFriend.IsListViewInit then
                self.LoopListFriend:InitListView(#self.friendRequest, Bind(self, self.OnGetItemByIndex))
            else
                GameUtils.ReloadData(self.LoopListFriend, #self.friendRequest)
            end
        else
            self.FontStyleButton:GetComponent("FontStyleButton"):ResetFontStyle("B6", localize("搜索"))
            self.cellType = Constants.FriendCellType.RecommendList
            self:FreshAddFriendPanel(self.recommendFriendList)
        end
        -- 在添加好友页签里面不显示红点
        local redPointGo = GameUtils.GetRedPointGo(self.FontStyleButton.gameObject)
        KTool.SetActive(redPointGo, false)
    end
end

function FriendMain:OnClickSearchBtn()
    local txtInput = self.InputField.text
    if txtInput == '' then
        GameUtils.Toast(localize("请输入ID或用户名"))
        return
    end
    GameUtils.Request(
            Interfaces.FriendFindFriend,
            {
                friend = checkString(txtInput)
            },
            function(request, response)
                if checkInt(response.errCode) == 0 then
                    if isNull(response.data.friend) then
                        GameUtils.Toast(localize("未找到对应目标"))
                    else
                        self:FreshAddFriendPanel({response.data.friend})
                    end
                end
            end
    )
end

function FriendMain:OnClickRefreshBtn()
    GameUtils.SecondConfirm(
            localize("是否刷新好友？"),
            function()
                GameUtils.Request(
                        Interfaces.FriendRefreshRecommendFriend,
                        {},
                        function(request, response)
                            if checkInt(response.errCode) == 0 then
                                self.recommendFriendList = response.data.recommendFriendList
                                self:OnClickTabToggleAction(OpenType.AddFriend)
                            end
                        end
                )
            end
    )
end

function FriendMain:OneClickBtnHandler()
    if self.isFriendList then--一键处理  先赠送后领取
        if #self.friendList > 0 then
            if not ((#self.drawFriendIds >= self.maxDrawFriendGift) and (#self.giveFriendIds >= self.maxGiveFriendGift)) then-- not 领取赠送都上限了
                friendComponent:OneKeyProcessingFriendList(function(drawFriendNum)
                    self:FreshLeftReceiveTime(drawFriendNum)
                    self:OnClickTabToggleAction(OpenType.FriendList)
                    GameUtils.SetRedPointNum(Constants.RedPointConst.FriendGiftOneClick, (#self.drawFriendIds < self.maxDrawFriendGift and friendComponent:HasUnclaimedGift()) and 1 or 0)--有未领取的体力且领取次数没到上限
                end)
            end
            GameUtils.Toast(localize("处理完成"))
        else
            GameUtils.Toast(localize("暂无好友"))
        end
    else
        if #self.friendRequest > 0 then--一键同意
            self:GoToAddOrRefuseFriend(true)
        else--搜索
            self:OnClickSearchBtn()
        end
    end
end

---刷新添加好友的面板，可传入搜索和推荐的好友
function FriendMain:FreshAddFriendPanel(datas)
    local goCount = self.Layout.transform.childCount
    if goCount > #datas then
        for i = #datas + 1, goCount do --复用时隐藏多出来的
            KTool.SetActive(self.Layout.transform:Find("Node"..i), false)
        end
    end
    --printInfo("==========>>"..table.dump(datas))
    for i = 1, #datas do
        local node
        node = self.Layout.transform:Find("Node"..i)
        if not node then
            node = CfUtils.InstantiateGo(self.Cell, self.Layout.gameObject)
            node.name = "Node"..i
        end
        local position = node.transform.localPosition
        node.transform.localPosition = Vector3.New(position.x, position.y, 0)
        local nodeEnv = CfUtils.GetLuaScr(node, "Game.UI.Friend.FriendMainInfoNode")
        local data = datas[i]
        local func = {
            add = function()
                friendComponent:AddFriend(data.friendId, function ()
                    nodeEnv:SetBtnAddGray(true)
                end)
            end
        }
        CfUtils.PlayDelayShowAnimate(node, i)
        KTool.SetActive(node, true)
        nodeEnv:FreshBaseUI(data, func, self.cellType)
    end
end

function FriendMain:OnGetItemByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem("Cell")
    local node = GetLuaBehaviour(cell.gameObject, "Game.UI.Friend.FriendMainInfoNode")
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
        node:Init()
    end
    if not KTool.IsNull(node) then
        local data
        local func
        local luaIndex = index + 1
        CfUtils.AdaptiveParentWidth(node, listView.ViewPortWidth)
        if self.cellType == Constants.FriendCellType.FriendList then
            data = self.friendList[luaIndex]
            func = {
                give = function()
                    friendComponent:GiveGift(data.friendId,
                            function()
                                node.Env:SetBtnGiveGray(true)
                            end)
                end,
                draw = function()
                    friendComponent:DrawGift(data.friendId,
                            function(drawFriendNum)
                                node.Env:SetBtnDrawGray(true)
                                self:FreshLeftReceiveTime(drawFriendNum)
                                --红点维护
                                GameUtils.SetRedPointNum(Constants.RedPointConst.FriendGiftOneClick, (#self.drawFriendIds < self.maxDrawFriendGift and friendComponent:HasUnclaimedGift()) and 1 or 0)--有未领取的体力且领取次数没到上限
                            end)

                end,
                pvp = function()--发送邀请
                    friendComponent:SendInvite(data.friendId)
                end
            }
        elseif self.cellType == Constants.FriendCellType.RequestList then
            data = self.friendRequest[luaIndex]
            func = {
                agree = function()
                    self:GoToAddOrRefuseFriend(true, data.friendId)
                end,
                refuse = function()
                    self:GoToAddOrRefuseFriend(false, data.friendId)
                end
            }
        elseif self.cellType == Constants.FriendCellType.RecommendList then
            data = self.recommendFriendList[luaIndex]
            func = {
                add = function()
                    --对方好友申请已满的情况服务端做判断
                    friendComponent:AddFriend(data.friendId, function ()
                        node.Env:SetBtnAddGray(true)
                    end)
                end
            }
        end
        --printInfo("data=====>>"..table.dump(data))
        --printInfo("friendList=====>>"..table.dump(self.friendList))
        --printInfo("dataType=====>>"..self.cellType)
        node.Env:FreshBaseUI(data, func, self.cellType)
        --@region 刚进入列表时播放延时出现动画
        if not isNull(self["isAnimated"..luaIndex]) then
            if not self["isAnimated"..luaIndex] then
                self["isAnimated"..luaIndex] = true
                CfUtils.PlayDelayShowAnimate(node, luaIndex)
            else
                CfUtils.PlayDelayShowAnimate(node, 0)
            end
        else
            CfUtils.PlayDelayShowAnimate(node, 0)
        end
        --@endregion
    end
    return cell
end

function FriendMain:GoToAddOrRefuseFriend(isAgree, friendId)
    local overLimit = false
    local addCount = checkInt(friendId) > 0 and 1 or #self.friendRequest
    if isAgree and #self.friendList + addCount > self.maxFriendNum then
        overLimit = true
    end

    GameUtils.Request(Interfaces.FriendHandleAddFriend, {
        agree = isAgree and 1 or 2, -- 同意
        friendId = friendId
    }, function(request, response)
        if checkInt(response.errCode) == 0 then
            friendComponent:MaintainFriendRequestData(response.data.agree, response.data.friendId,
                response.data.friendList, checkInt(friendId) <= 0, overLimit)
            if response.data.agree == 1 then
                self:FreshFriendCount()
            end
            -- 红点维护
            GameUtils.SetRedPointNum(Constants.RedPointConst.FriendRequest, #self.friendRequest)
            -- 刷新好友列表
            self:OnClickTabToggleAction(OpenType.AddFriend)

        end
    end)
end

---刷新界面左下的好友数量
function FriendMain:FreshFriendCount()
    CfUtils.FillText(self.TxtNumber, string.format("%s<size=33>/%s</size>", #self.friendList, self.maxFriendNum))
end

function FriendMain:FreshLeftReceiveTime(num)
    friendComponent:SetDrawFriendGiftNum(num)
    CfUtils.FillText(self.TxtTime, string.format("%s/%s", friendComponent:GetDrawFriendGiftNum(), self.maxDrawFriendGift))
end


return FriendMain